META = dict(nama="Wood Industry", jp="木材産業", emoji="🪵", co="製材所・木材加工会社")
SPEC = dict(kerja="木材を安全に、ていねいに加工している", kerja_id="mengolah kayu dengan aman dan teliti", soal={
 "shibou-01": ("なぜ木材産業の仕事を選びましたか。", "Mengapa Anda memilih pekerjaan industri kayu?", "木のにおいや、手ざわりが好きです。木から家具や建物の材料を作る仕事に、興味があります。", "Saya suka bau dan tekstur kayu. Saya tertarik pada pekerjaan membuat bahan furnitur dan bangunan dari kayu.", [("木材", "kayu"), ("手ざわり", "tekstur sentuhan"), ("材料", "bahan"), ("加工", "pengolahan")]),
 "shibou-02": ("なぜ日本で木材の仕事を学びたいですか。", "Mengapa Anda ingin belajar pekerjaan kayu di Jepang?", "日本の木材加工は、細かくて、品質がとても高いと聞きました。その技術を学んで、将来に生かしたいです。", "Saya dengar pengolahan kayu Jepang sangat teliti dan berkualitas tinggi. Saya ingin mempelajarinya dan memanfaatkannya kelak.", [("技術", "teknik"), ("品質", "kualitas"), ("学ぶ", "belajar")]),
 "shibou-04": ("この仕事に興味を持った理由は何ですか。", "Apa alasan Anda tertarik pada pekerjaan ini?", "木が、きれいな板や材料になっていくのを見るのが好きです。ものを作る仕事がしたいです。", "Saya suka melihat kayu menjadi papan dan bahan yang rapi. Saya ingin bekerja membuat sesuatu.", [("板", "papan"), ("興味", "minat"), ("やりがい", "rasa bermakna")]),
 "shibou-05": ("木材の仕事で、一番楽しみなことは何ですか。", "Apa yang paling Anda nantikan dari pekerjaan kayu?", "機械の使い方を覚えて、きれいに木を切れるようになることです。日本の技術も学びたいです。", "Belajar memakai mesin dan bisa memotong kayu dengan rapi. Saya juga ingin belajar teknik Jepang.", [("切る", "memotong"), ("機械", "mesin"), ("楽しみ", "dinantikan")]),
 "shigoto-01": ("木材産業の主な仕事は何だと思いますか。", "Menurut Anda, apa pekerjaan utama industri kayu?", "丸太を切って、板や角材にする仕事だと思います。乾かしたり、形を整えたりする仕事もあります。", "Saya kira pekerjaannya memotong gelondongan menjadi papan dan balok. Ada juga mengeringkan dan merapikan bentuk.", [("丸太", "gelondongan kayu"), ("角材", "balok kayu"), ("乾燥", "pengeringan")]),
 "shigoto-02": ("朝早くから働くことはできますか。", "Apakah Anda bisa bekerja dari pagi buta?", "はい、できます。早く寝て、朝の準備をしっかりします。", "Ya, bisa. Saya tidur lebih awal dan bersiap dengan baik di pagi hari.", [("早起き", "bangun pagi"), ("準備", "persiapan"), ("体調", "kondisi badan")]),
 "shigoto-03": ("木くずやほこりが多い環境でも大丈夫ですか。", "Apakah Anda baik-baik saja di lingkungan yang banyak serbuk kayu dan debu?", "はい、大丈夫です。マスクとめがねをつけて、体を守ります。作業のあとは、よく掃除します。", "Ya, tidak masalah. Saya memakai masker dan kacamata untuk melindungi badan. Setelah kerja saya membersihkan dengan baik.", [("木くず", "serbuk kayu"), ("ほこり", "debu"), ("マスク", "masker")]),
 "shigoto-04": ("大きい機械の音がする工場でも大丈夫ですか。", "Apakah Anda baik-baik saja di pabrik dengan suara mesin yang besar?", "はい、大丈夫です。耳せんをつけて、大きい音から耳を守ります。", "Ya, tidak masalah. Saya memakai penyumbat telinga untuk melindungi telinga dari suara keras.", [("音", "suara"), ("耳せん", "penyumbat telinga"), ("機械", "mesin")]),
 "shigoto-05": ("体力が必要な仕事ですが、大丈夫ですか。", "Pekerjaan ini butuh stamina, apakah Anda baik-baik saja?", "はい、大丈夫です。毎日運動をして、体力をつけています。重い木は、一人で持たないようにします。", "Ya, tidak masalah. Saya berolahraga setiap hari. Kayu berat tidak saya angkat sendirian.", [("体力", "stamina"), ("重い", "berat"), ("運動", "olahraga")]),
 "shigoto-06": ("注文が多いとき、残業があっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan lembur saat pesanan banyak?", "はい、大丈夫です。忙しい時期は、チームでがんばります。体調にも気をつけます。", "Ya, tidak masalah. Saat sibuk kami berusaha bersama. Saya juga menjaga kondisi badan.", [("注文", "pesanan"), ("残業", "lembur"), ("チーム", "tim")]),
 "shigoto-07": ("のこぎりや機械を使うとき、何に気をつけますか。", "Apa yang Anda perhatikan saat memakai gergaji dan mesin?", "使う前に、刃や機械の状態を確認します。動いている刃には、絶対に手を近づけません。", "Sebelum dipakai saya memeriksa kondisi mata gergaji dan mesin. Saya tidak pernah mendekatkan tangan ke mata gergaji yang bergerak.", [("刃", "mata pisau/gergaji"), ("確認", "memastikan"), ("絶対に", "sama sekali")]),
 "shigoto-08": ("木のにおいや、木くずが体に合わないことがあっても大丈夫ですか。", "Bagaimana kalau bau kayu atau serbuk kayu tidak cocok dengan tubuh Anda?", "体に合わないと感じたら、すぐに責任者に言います。マスクを使って、無理をしません。", "Kalau terasa tidak cocok, saya segera memberi tahu penanggung jawab. Saya memakai masker dan tidak memaksakan diri.", [("体に合わない", "tidak cocok dengan badan"), ("マスク", "masker"), ("無理", "memaksakan")]),
 "shigoto-09": ("木材を扱う仕事で、大切なことは何だと思いますか。", "Menurut Anda, apa yang penting dalam pekerjaan menangani kayu?", "寸法を正しく測ることと、安全に作業することだと思います。木によって、かたさが違うことにも気をつけます。", "Menurut saya, mengukur dengan benar dan bekerja dengan aman. Saya juga memperhatikan bahwa kekerasan tiap kayu berbeda.", [("寸法", "ukuran"), ("測る", "mengukur"), ("かたさ", "kekerasan")]),
 "shigoto-10": ("丸太が届いてから、製品になるまで、どんな作業がありますか。", "Apa saja proses sejak gelondongan kayu tiba sampai menjadi produk?", "丸太を切って、乾かして、形を整えます。最後に検査をして、出荷します。", "Gelondongan dipotong, dikeringkan, dan dirapikan bentuknya. Terakhir diperiksa lalu dikirim.", [("乾燥", "pengeringan"), ("検査", "inspeksi"), ("出荷", "pengiriman")]),
 "shigoto-11": ("木の曲がりや、傷を見つけたら、どうしますか。", "Apa yang Anda lakukan kalau menemukan kayu bengkok atau cacat?", "勝手に使わないで、先輩に見せます。使えるか、使えないか、教えてもらいます。", "Saya tidak memakainya sembarangan, tetapi menunjukkannya kepada senior dan menanyakan bisa dipakai atau tidak.", [("曲がり", "bengkok"), ("傷", "cacat/goresan"), ("見せる", "menunjukkan")]),
 "shigoto-12": ("きれいな製品を作るために、何に気をつけますか。", "Apa yang Anda perhatikan agar produk rapi dan bagus?", "寸法を何度も確認します。表面に傷をつけないように、ていねいに運びます。", "Saya memeriksa ukuran berulang kali. Saya memindahkannya dengan hati-hati agar permukaan tidak tergores.", [("寸法", "ukuran"), ("表面", "permukaan"), ("ていねい", "teliti")]),
 "shigoto-13": ("決まった数や長さに、そろえる作業は得意ですか。", "Apakah Anda pandai pekerjaan menyeragamkan jumlah dan panjang?", "はい、正確に数えたり、測ったりするのは得意です。ミスをしないように、二回確認します。", "Ya, saya pandai menghitung dan mengukur dengan akurat. Agar tidak salah, saya memeriksa dua kali.", [("そろえる", "menyeragamkan"), ("数える", "menghitung"), ("得意", "pandai")]),
 "taiou-02": ("木を間違った長さに切ってしまったら、どうしますか。", "Apa yang Anda lakukan kalau memotong kayu dengan panjang yang salah?", "すぐに正直に報告します。どうして間違えたか考えて、次は測り方を二回確認します。", "Saya segera melapor jujur. Saya memikirkan penyebabnya dan lain kali memeriksa cara mengukur dua kali.", [("長さ", "panjang"), ("報告", "melapor"), ("測る", "mengukur")]),
 "taiou-06": ("急に、仕事の内容や予定が変わったら、どうしますか。", "Apa yang Anda lakukan kalau isi atau rencana kerja berubah mendadak?", "責任者の指示をよく聞いて、新しい作業を始めます。分からないときは、すぐに聞きます。", "Saya mendengarkan instruksi penanggung jawab dan memulai pekerjaan baru. Kalau tidak paham, saya segera bertanya.", [("急に", "mendadak"), ("指示", "instruksi"), ("予定", "rencana")]),
 "taiou-08": ("機械が止まったり、変な音がしたりしたら、どうしますか。", "Apa yang Anda lakukan kalau mesin berhenti atau berbunyi aneh?", "すぐに機械を止めて、責任者に知らせます。自分で直さないようにします。", "Saya segera menghentikan mesin dan memberi tahu penanggung jawab. Saya tidak memperbaikinya sendiri.", [("変な音", "bunyi aneh"), ("止める", "menghentikan"), ("知らせる", "memberi tahu")]),
 "taiou-11": ("忙しい時期で、疲れているとき、どう気持ちを保ちますか。", "Bagaimana Anda menjaga semangat saat sibuk dan lelah?", "忙しい時期は短いと理解しています。しっかり寝て、食事をとって、体調を保ちます。", "Saya paham musim sibuk itu singkat. Saya tidur cukup, makan baik, dan menjaga kondisi badan.", [("疲れる", "lelah"), ("体調", "kondisi badan"), ("睡眠", "tidur")]),
 "taiou-12": ("先輩の説明が早くて、分からないとき、どうしますか。", "Apa yang Anda lakukan kalau penjelasan senior terlalu cepat dan tidak Anda pahami?", "「すみません、もう一度ゆっくりお願いします」と言います。分からない言葉は、メモして、あとで聞きます。", "Saya bilang \"Maaf, tolong ulangi lebih pelan\". Kata yang tidak paham saya catat dan tanyakan nanti.", [("説明", "penjelasan"), ("ゆっくり", "pelan"), ("メモ", "catatan")]),
 "tim-01": ("丸太や材料を運ぶとき、チームの人と、どのように作業しますか。", "Saat memindahkan gelondongan atau bahan, bagaimana Anda bekerja dengan tim?", "声をかけ合って、タイミングを合わせて運びます。重いときは、ほかの人にも頼みます。", "Kami saling memberi aba-aba dan memindahkan dengan waktu yang serempak. Kalau berat, saya minta bantuan orang lain.", [("声をかけ合う", "saling memberi aba-aba"), ("タイミング", "waktu yang tepat"), ("頼む", "meminta bantuan")]),
 "tim-02": ("先輩の指示が分からなかったとき、どうしますか。", "Apa yang Anda lakukan kalau tidak paham instruksi senior?", "すぐに「もう一度お願いします」と聞きます。分からないまま機械を使うと、危ないからです。", "Saya segera meminta \"Tolong ulangi\". Memakai mesin tanpa paham itu berbahaya.", [("指示", "instruksi"), ("危ない", "berbahaya"), ("確認", "memastikan")]),
 "tim-03": ("機械を使うとき、まわりの人と、どのようにコミュニケーションをとりますか。", "Bagaimana Anda berkomunikasi dengan orang sekitar saat memakai mesin?", "動かす前に、大きい声で「動かします」と言います。まわりの人が離れたか、必ず見ます。", "Sebelum menyalakan, saya berkata keras \"Saya nyalakan\". Saya selalu memeriksa apakah orang sekitar sudah menjauh.", [("声をかける", "memberi aba-aba"), ("離れる", "menjauh"), ("確認", "memastikan")]),
 "tim-04": ("職場の仲間と、どのように仲良くなりたいですか。", "Bagaimana Anda ingin akrab dengan rekan kerja?", "毎日、元気にあいさつをします。教えてもらったときは、「ありがとうございます」と言います。", "Setiap hari saya menyapa dengan semangat. Saat diajari, saya mengatakan \"Terima kasih\".", [("あいさつ", "salam"), ("仲間", "rekan"), ("仲良くなる", "menjadi akrab")]),
 "anzen-01": ("作業をするとき、必ず身につけるものは何ですか。", "Apa yang wajib dikenakan saat bekerja?", "ヘルメット、安全靴、保護めがね、マスクを必ず着けます。耳せんも使います。", "Saya wajib memakai helm, sepatu keselamatan, kacamata pelindung, dan masker. Saya juga memakai penyumbat telinga.", [("ヘルメット", "helm"), ("保護めがね", "kacamata pelindung"), ("安全靴", "sepatu keselamatan")]),
 "anzen-02": ("のこぎりや、動いている刃の近くで、どうしますか。", "Apa yang Anda lakukan di dekat gergaji atau mata pisau yang bergerak?", "手や服を近づけません。刃が完全に止まるまで、さわりません。掃除のときは、必ず電源を切ります。", "Saya tidak mendekatkan tangan atau pakaian. Saya tidak menyentuhnya sampai mata gergaji benar-benar berhenti. Saat membersihkan, saya selalu mematikan daya.", [("刃", "mata gergaji"), ("電源", "daya listrik"), ("完全に", "sepenuhnya")]),
 "anzen-03": ("木くずが多いとき、どんなことに気をつけますか。", "Apa yang Anda perhatikan saat serbuk kayu banyak?", "こまめに掃除して、床がすべらないようにします。火の近くには、木くずを置きません。", "Saya sering membersihkan agar lantai tidak licin. Serbuk kayu tidak saya taruh dekat api.", [("木くず", "serbuk kayu"), ("火災", "kebakaran"), ("掃除", "membersihkan")]),
 "anzen-04": ("重い木材を運ぶとき、どうしますか。", "Apa yang Anda lakukan saat mengangkat kayu berat?", "一人で持てないときは、ほかの人に頼みます。腰を曲げないで、ひざを使って持ち上げます。足の上に落とさないよう気をつけます。", "Kalau tidak sanggup sendiri, saya minta bantuan orang lain. Saya mengangkat dengan menekuk lutut, bukan membungkuk dari pinggang. Saya berhati-hati agar tidak menjatuhkannya ke kaki.", [("腰", "pinggang"), ("ひざ", "lutut"), ("落とす", "menjatuhkan")]),
 "seikatsu-07": ("山の近くの町での生活に、不便なことがあっても大丈夫ですか。", "Apakah Anda baik-baik saja dengan ketidaknyamanan hidup di kota dekat pegunungan?", "大丈夫です。お店が遠いときは、まとめて買い物をします。バスの時間も調べます。", "Tidak masalah. Kalau toko jauh, saya belanja sekaligus. Saya juga mengecek jadwal bus.", [("不便", "tidak nyaman"), ("まとめて", "sekaligus"), ("調べる", "mengecek")]),
 "seikatsu-08": ("日本の木や、木の文化について、知っていることはありますか。", "Apa yang Anda ketahui tentang kayu dan budaya kayu Jepang?", "日本には、木の家やお寺がたくさんあると聞きました。ヒノキやスギが有名なことも知っています。", "Saya dengar di Jepang banyak rumah dan kuil dari kayu. Saya juga tahu hinoki dan sugi terkenal.", [("ヒノキ", "cemara hinoki"), ("スギ", "cedar sugi"), ("お寺", "kuil")]),
 "mokuhyou-05": ("日本で木材の仕事を学んだあと、自分の国でどんなことをしたいですか。", "Setelah belajar pekerjaan kayu di Jepang, apa yang ingin Anda lakukan di negara sendiri?", "日本で学んだ木の加工の技術と、安全の方法を使って、自分の国で木の仕事をしたいです。", "Saya ingin bekerja di bidang kayu di negara saya dengan memakai teknik pengolahan kayu dan cara keselamatan yang saya pelajari di Jepang.", [("加工", "pengolahan"), ("安全", "keselamatan"), ("技術", "teknik")]),
})
